// Dokumente, bei denen mindestens eins der Felder dranhängt, aber leer ist, und die noch keinen Tag "KI-Felder" haben.
const F = Object.fromEntries(($('Felder').first().json.results || []).map(f => [f.name, f.id]));
const NAMES = ['Betrag', 'Fällig am', 'Vertragsende', 'Kündigen bis', 'Steuerjahr'];
for (const n of NAMES) if (!F[n]) throw new Error(`Custom Field "${n}" fehlt (paperless-setup.py laufen lassen)`);
const kiTag = ($('Tag KI-Felder').first().json.results || [])[0];
if (!kiTag) throw new Error('Tag "KI-Felder" fehlt oder ist für n8n nicht sichtbar (paperless-setup.py laufen lassen)');
const leer = NAMES.map(n => ['AND', [[F[n], 'exists', true], [F[n], 'isnull', true]]]);
return [{ json: { F, kiTag: kiTag.id, query: JSON.stringify(['OR', leer]) } }];

// Ein Item pro Dokument, mit fertigem Prompt. Nur Felder, die am Dokument hängen und leer sind, werden erfragt.
const cfg = $('Config').first().json;
const { F } = $('Abfrage').first().json;
const KEYS = { 'Betrag': 'betrag', 'Fällig am': 'faellig_am', 'Vertragsende': 'vertragsende',
               'Kündigen bis': 'kuendigen_bis', 'Steuerjahr': 'steuerjahr' };
const HILFE = {
  betrag: 'Gesamtbetrag der Rechnung in Euro, brutto, den man zahlen muss (Zahl mit Punkt als Dezimaltrenner)',
  faellig_am: 'Fälligkeitsdatum. Steht nur "zahlbar innerhalb von X Tagen", dann Rechnungsdatum + X Tage. Bei Lastschrift das Abbuchungsdatum',
  vertragsende: 'Datum, an dem die Vertragslaufzeit endet (bei automatischer Verlängerung das Ende der aktuellen Laufzeit)',
  kuendigen_bis: 'Letzter Tag, an dem die Kündigung beim Anbieter sein muss (Vertragsende minus Kündigungsfrist)',
  steuerjahr: 'Kalenderjahr, für das das Dokument steuerlich gilt (z. B. Lohnsteuerbescheinigung 2025 -> 2025)',
};
const docs = $('Dokumente').first().json.results || [];
return docs.map(d => {
  const leer = (d.custom_fields || []).filter(c => c.value === null || c.value === '')
    .map(c => Object.keys(F).find(n => F[n] === c.field)).filter(n => KEYS[n]).map(n => KEYS[n]);
  const text = String(d.content || '').slice(0, cfg.maxZeichen);
  const props = Object.fromEntries(leer.map(k => [k, { type: k === 'betrag' ? ['number', 'null'] : k === 'steuerjahr' ? ['integer', 'null'] : ['string', 'null'] }]));
  const prompt = [
    `Lies aus dem folgenden Dokument diese Werte aus. Datumsangaben als YYYY-MM-DD. Wenn ein Wert nicht eindeutig im Text steht, gib null zurück. Nichts raten.`,
    ...leer.map(k => `- ${k}: ${HILFE[k]}`),
    '', `Titel: ${d.title}`, `Dokumentdatum: ${d.created}`, '', 'Text:', text,
  ].join('\n');
  return { json: { id: d.id, title: d.title, tags: d.tags || [], custom_fields: d.custom_fields || [], leer,
    ollama: { model: cfg.model, stream: false, options: { temperature: 0, num_ctx: 8192 },
      format: { type: 'object', properties: props, required: leer },
      messages: [
        { role: 'system', content: 'Du liest deutsche Rechnungen, Verträge und Steuerdokumente aus. Antworte nur mit JSON nach dem vorgegebenen Schema.' },
        { role: 'user', content: prompt } ] } } };
}).filter(i => i.json.leer.length);

// Antwort prüfen und nur leere Felder füllen. Kam von Ollama nichts (Mac Studio schläft), bleibt das Dokument
// ohne Tag "KI-Felder" und wird beim nächsten Lauf erneut versucht.
const { F, kiTag } = $('Abfrage').first().json;
const KEYS = { betrag: 'Betrag', faellig_am: 'Fällig am', vertragsende: 'Vertragsende', kuendigen_bis: 'Kündigen bis', steuerjahr: 'Steuerjahr' };
const isDate = v => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v) && !isNaN(Date.parse(v));
const docs = $('Aufteilen').all();
const out = [];
$input.all().forEach((it, i) => {
  const d = docs[i]?.json;
  const content = it.json?.message?.content;
  if (!d || !content) return;
  let r;
  try { r = JSON.parse(content); } catch (e) { r = {}; }
  const werte = {};
  if (typeof r.betrag === 'number' && r.betrag > 0 && r.betrag < 1e7) werte[F['Betrag']] = 'EUR' + r.betrag.toFixed(2);
  for (const k of ['faellig_am', 'vertragsende', 'kuendigen_bis']) if (isDate(r[k])) werte[F[KEYS[k]]] = r[k];
  if (Number.isInteger(r.steuerjahr) && r.steuerjahr >= 2000 && r.steuerjahr <= 2100) werte[F['Steuerjahr']] = r.steuerjahr;
  // PATCH ersetzt die ganze Liste: alle vorhandenen Felder mitschicken, nur leere bekommen den neuen Wert
  const custom_fields = d.custom_fields.map(c => ({ field: c.field,
    value: (c.value === null || c.value === '') && c.field in werte ? werte[c.field] : c.value }));
  const gefuellt = Object.entries(werte).filter(([f]) => d.custom_fields.some(c => c.field === Number(f) && (c.value === null || c.value === '')))
    .map(([f, v]) => `${Object.keys(F).find(n => F[n] === Number(f))}=${v}`);
  out.push({ json: { id: d.id, title: d.title, gefuellt,
    body: { custom_fields, tags: [...new Set([...d.tags, kiTag])] } } });
});
return out;
